theorem extracted_formal_statement_2 {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {n : ℕ} {f : 𝕜 → 𝕜}
  (h : ContDiff 𝕜 (↑n) f) (c : 𝕜) :
  (iteratedDeriv n fun x => f (c * x)) = fun x => c ^ n * iteratedDeriv n f (c * x) := sorry

